service.method:

	UPDATE SDEPT SET
     	DEPT_NAME_LOC = ${DEPT_NAME_LOC}, 
		DEPT_NAME_ENG = ${DEPT_NAME_ENG}, 
		DEPT_NAME_JP = ${DEPT_NAME_JP}, 
		DEPT_NAME_CN = ${DEPT_NAME_CN}, 
		PARENT_DEPT = ${PARENT_DEPT}
	WHERE HOUSE_CODE = ${session.HOUSE_CODE}
	   AND COMPANY_CODE = ${COMPANY_CODE}
	   AND DEPT = ${DEPT}
	   AND NVL(DEL_FLAG, 'N') = 'N'


UPDATE SDEPT
SET DEL_FLAG = 'Y'
WHERE HOUSE_CODE = ${session.HOUSE_CODE}
	AND COMPANY_CODE = ${COMPANY_CODE}
	AND DEPT = ${DEPT}


UPDATE SDEPT
SET DEL_FLAG = 'Y'
WHERE HOUSE_CODE = ${session.HOUSE_CODE}
	AND COMPANY_CODE = ${COMPANY_CODE}


    	SELECT COMPANY_CODE
    	FROM SCMGL
		WHERE HOUSE_CODE   = ${session.HOUSE_CODE}
		  AND COMPANY_CODE      = ${COMPANY_CODE}
		  AND DEL_FLAG	   = 'N'


		INSERT INTO SCMGL (
			HOUSE_CODE
			, COMPANY_CODE
			, LANGUAGE 	 	   
			, COMPANY_NAME_LOC  
			, COMPANY_NAME_ENG  
			, CUR               
			, COUNTRY           
			, CITY_CODE         
			, IRS_NO            
			, DUNS_NO           
			, FOUNDATION_DATE   
			, GROUP_COMPANY_CODE
			, GROUP_COMPANY_NAME
			, CREDIT_RATING     
			, INDUSTRY_TYPE     
			, BUSINESS_TYPE     
			, TRADE_AGENCY_NO   
			, TRADE_AGENCY_NAME 
			, EDI_ID            
			, EDI_QUALIFIER     
			, INS_COM_CODE
			, CHANGE_DATE    
			, CHANGE_TIME    
			, CHANGE_USER_ID 
			, ADD_DATE   
			, ADD_TIME   
			, ADD_USER_ID
			, DEL_FLAG    
			, ATTACH_NO   
			, REPRESENTATIVE_COMPANY_FLAG
			, ADDRESS_LOC
			, CEO_NAME_LOC
			, ADDRESS_ENG
			, ZIP_CODE
			, PHONE_NO1
			, HOMEPAGE
		) VALUES (
			${session.HOUSE_CODE}
			, ${COMPANY_CODE}
 			, ${LANGUAGE}          
			, ${COMPANY_NAME_LOC}  
			, ${COMPANY_NAME_ENG}  
			, ${CUR}               
			, ${COUNTRY}           
			, ${CITY_CODE}         
			, ${IRS_NO}            
			, ${DUNS_NO}           
			, ${FOUNDATION_DATE}   
			, ${GROUP_COMPANY_CODE}
			, ${GROUP_COMPANY_NAME}
			, ${CREDIT_RATING}     
			, ${INDUSTRY_TYPE}     
			, ${BUSINESS_TYPE}     
			, ${TRADE_AGENCY_NO}   
			, ${TRADE_AGENCY_NAME} 
			, ${EDI_ID}            
			, ${EDI_QUALIFIER}     
			, ${INS_COM_CODE}   
			, ${current.date}    
			, ${current.time}
			, ${session.ID}
			, ${current.date}    
			, ${current.time}    
			, ${session.ID}   
			, ${DEL_FLAG}
			, ${ATTACH_NO}  
			, ${REPRESENTATIVE_COMPANY_FLAG}
			, ${ADDRESS_LOC}
			, ${CEO_NAME}
			, ${ADDRESS_ENG}
			, ${ZIP_CODE}
			, ${PHONE_NO1}
			, ${HOMEPAGE}
		)


UPDATE SCMGL SET
	  LANGUAGE = ${LANGUAGE}
	, COMPANY_NAME_LOC = ${COMPANY_NAME_LOC}      
	, COMPANY_NAME_ENG = ${COMPANY_NAME_ENG}      
	, CUR = ${CUR}      
	, COUNTRY = ${COUNTRY}      
	, CITY_CODE = ${CITY_CODE}      
	, IRS_NO = ${IRS_NO}      
	, DUNS_NO = ${DUNS_NO}      
	, FOUNDATION_DATE = ${FOUNDATION_DATE}      
	, GROUP_COMPANY_CODE = ${GROUP_COMPANY_CODE}      
	, GROUP_COMPANY_NAME = ${GROUP_COMPANY_NAME}      
	, CREDIT_RATING = ${CREDIT_RATING}      
	, INDUSTRY_TYPE = ${INDUSTRY_TYPE}        
	, BUSINESS_TYPE = ${BUSINESS_TYPE}      
	, TRADE_AGENCY_NO = ${TRADE_AGENCY_NO}      
	, TRADE_AGENCY_NAME = ${TRADE_AGENCY_NAME}      
	, EDI_ID = ${EDI_ID}      
	, EDI_QUALIFIER = ${EDI_QUALIFIER}      
	, INS_COM_CODE = ${INS_COM_CODE}   
	, CHANGE_DATE = ${current.date}      
	, CHANGE_TIME = ${current.time}
	, CHANGE_USER_ID = ${session.ID}   
	, DEL_FLAG = ${DEL_FLAG}
	, ATTACH_NO = ${ATTACH_NO}  
	, REPRESENTATIVE_COMPANY_FLAG = ${REPRESENTATIVE_COMPANY_FLAG}
	, ADDRESS_LOC  = ${ADDRESS_LOC}
	, CEO_NAME_LOC = ${CEO_NAME}
	, ADDRESS_ENG = ${ADDRESS_ENG}
	, ZIP_CODE = ${ZIP_CODE}
	, PHONE_NO1 = ${PHONE_NO1}
	, HOMEPAGE = ${HOMEPAGE}
WHERE HOUSE_CODE = ${session.HOUSE_CODE}
   AND COMPANY_CODE = ${COMPANY_CODE}


UPDATE SCMGL
SET DEL_FLAG = 'Y'
 WHERE HOUSE_CODE   = ${session.HOUSE_CODE}
   AND COMPANY_CODE = ${COMPANY_CODE}


    	SELECT COMPANY_CODE
    	FROM SCMGL
		WHERE HOUSE_CODE   = ${session.HOUSE_CODE}
		  AND COMPANY_CODE      = ${COMPANY_CODE}


    	SELECT DEPT,
    		DEL_FLAG
    	FROM SDEPT
		WHERE HOUSE_CODE   = ${session.HOUSE_CODE}
		  AND COMPANY_CODE = ${COMPANY_CODE}
		  AND DEPT      = ${DEPT}


    	SELECT DEL_FLAG
    	FROM SBAGL
		WHERE HOUSE_CODE   = ${session.HOUSE_CODE}
		  AND COMPANY_CODE = ${COMPANY_CODE}
		  AND CTRL_CODE    = ${CTRL_CODE}


    	SELECT DEL_FLAG
    	FROM SBALN
		WHERE HOUSE_CODE   = ${session.HOUSE_CODE}
		  AND COMPANY_CODE = ${COMPANY_CODE}
		  AND CTRL_CODE    = ${CTRL_CODE}
		  AND CTRL_PERSON_ID = ${CTRL_PERSON_ID}


SELECT COMPANY_CODE
      , COMPANY_NAME_LOC
  FROM SCMGL
 WHERE HOUSE_CODE       = ${session.HOUSE_CODE}
   AND COMPANY_CODE     = $S{COMPANY_CODE}
   AND (    1=1
   		AND COMPANY_NAME_LOC LIKE '%' || $S{F_KEYWORD} || '%'
   		 OR COMPANY_CODE     LIKE '%' || $S{F_KEYWORD} || '%'
   )
   AND DEL_FLAG = 'N'


DELETE FROM
	SBAGL
WHERE HOUSE_CODE = ${session.HOUSE_CODE}
	AND COMPANY_CODE = ${COMPANY_CODE}
	AND CTRL_CODE = ${CTRL_CODE}
	AND CTRL_NUMBER = ${CTRL_NUMBER}


UPDATE SBAGL
SET DEL_FLAG = 'Y'
WHERE HOUSE_CODE = ${session.HOUSE_CODE}
	AND COMPANY_CODE = ${COMPANY_CODE}


UPDATE SBALN SET
	COMPANY_CODE = ${COMPANY_CODE}, 
	CTRL_CODE = ${CTRL_CODE}, 
	CTRL_PERSON_ID = ${CTRL_PERSON_ID}, 
	CTRL_TYPE = ${CTRL_TYPE}, 
	REPRESENT_CTRL = ${REPRESENT_CTRL}, 
	APP_ORDER       = $S{APP_ORDER},
 	CHANGE_DATE     = ${current.date}, 
 	CHANGE_TIME     = ${current.time}, 
 	CHANGE_USER_ID  = ${session.ID}
WHERE
	HOUSE_CODE = ${session.HOUSE_CODE}
	AND COMPANY_CODE = ${COMPANY_CODE}
	AND CTRL_CODE = ${CTRL_CODE}
	AND CTRL_PERSON_ID = ${CTRL_PERSON_ID}
	AND NVL(DEL_FLAG, 'N') = 'N'


DELETE FROM 
	SBALN
WHERE HOUSE_CODE = ${session.HOUSE_CODE}
	AND COMPANY_CODE = ${COMPANY_CODE}
	AND CTRL_CODE = ${CTRL_CODE}
	AND CTRL_PERSON_ID = ${CTRL_PERSON_ID}


DELETE FROM 
	SBALN
WHERE HOUSE_CODE = ${session.HOUSE_CODE}
	AND COMPANY_CODE = ${COMPANY_CODE}
	AND CTRL_CODE = $S{CTRL_CODE}


SELECT 
	COUNT(*) AS CNT
FROM SUSMT 
WHERE HOUSE_CODE = ${session.HOUSE_CODE}
  AND COMPANY_CODE = ${COMPANY_CODE}
  AND USER_ID = ${PERSON_ID}
  AND DEL_FLAG ='N'


    	SELECT DEPT
    	FROM SDEPT
		WHERE
			HOUSE_CODE	= ${session.HOUSE_CODE}
		AND DEPT		= ${DEPT}
		AND NVL(DEL_FLAG,  'N') = 'N'


    	SELECT DEPT
    	FROM SDEPT
		WHERE
			HOUSE_CODE	= ${session.HOUSE_CODE}
		AND DEPT		= ${PARENT_DEPT_NAME}
		AND NVL(DEL_FLAG,  'N') = 'N'


	INSERT 
	  INTO #DB_OWNER#SCODE
         ( HOUSE_CODE
         , TYPE
         , CODE
         , LANGUAGE
         , ADD_DATE
         , ADD_TIME
         , ADD_USER_ID
         , CHANGE_DATE
         , CHANGE_TIME
         , CHANGE_USER_ID
         , FLAG
         , SORT_SEQ
         , USE_FLAG
         , TEXT1
         , DEL_FLAG  
         )
   VALUES( 
           ${session.HOUSE_CODE}
         , 'UX049'
         , ${POSITION}
         , 'KO'
         , ${current.DATE}
         , ${current.TIME}
         , ${session.ID}
         , ${current.DATE}
         , ${current.TIME}
         , ${session.ID}
         , ${FLAG}
         , #{SORT_SEQ}
         , 'Y'
         , ${POSITION_NAME}
         , 'N'  
       )


UPDATE SCODE
SET DEL_FLAG = 'Y'
WHERE 
	HOUSE_CODE = ${session.HOUSE_CODE}
AND TYPE = 'UX049'
AND TEXT1 = ${POSITION_NAME}
